import{_ as l,l as o,o as e,c as r,v as t,p as i,x as E,d as n,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"掩模粗糙度","description":"","frontmatter":{"title":"掩模粗糙度","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-roughness.md","filePath":"litho/mask-roughness.md","lastUpdated":1789023840000}'),p={name:"litho/mask-roughness.md"};function u(m,a,c,A,B,_){const s=o("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="掩模粗糙度" tabindex="-1">掩模粗糙度 <a class="header-anchor" href="#掩模粗糙度" aria-label="Permalink to &quot;掩模粗糙度&quot;">​</a></h1><div class="epigraph"><p>胶的 LER 不全是光子和酸。掩模吸收体边沿的粗糙经光学传递，成为硅片上抹不掉的低频底噪。</p><footer>—— 据 Naulleau 对 mask roughness 与 LER；Mack 边缘粗糙框架</footer></div><p><a href="/litho/mask-3d-best-focus-shift">上一课</a>把三维电磁写成平均焦移。缺口是边沿的随机：掩模粗糙度（mask roughness / mask LER）。修复能否在不毁掉多层的前提下改这块边，留给[下一课](/litho/euv-mask-repair）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BF 偏移是确定的、图形相关的。掩模粗糙是随机的、沿边沿的高度与位置涨落。EUV 的光学传递函数对掩模高频仍有一定响应，尤其低 \\(k_1\\) 时掩模误差增强因子（MEEF）大，掩模上 1 nm 的边沿噪声可以在硅片上放大。Naulleau 把 EUV LER 预算拆成：光子散粒、胶化学、以及掩模贡献——后一项不随剂量消失。加剂量压随机，掩模底噪会露出来。</p><p>缺口是把掩模 LER 从胶随机里分开，而不是再讲一次 RLS 三角。空白多层的相位粗糙（表面高度）与吸收体线边粗糙是两桶：前者更像散斑/对比噪声，后者更像边沿位置噪声。</p><p><span class="marginnote">DUV 掩模粗糙相对 \\(k_1\\) 往往可忽略。EUV 短波 + 高 MEEF 把它抬成一等项。不要用「掩模厂 CD 合格」代替粗糙频谱合格。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计量：掩模 SEM 或 AFM 得边沿 PSD；光化显微镜看打印后的传递。规格按频段：低频进 CDU/套刻，中高频进 LER/LWR。写入：电子束邻近、抗蚀剂和干法侧壁共同决定吸收体 PSD；多层沉积决定相位粗糙。OPC 不能「画平」随机边沿，只能避免把高 MEEF 图形放在粗糙最敏感的节距上。</p><p>与照明：极子改变传递函数，某些频率被放大。SMO 若只优化平均 NILS，可能选中对掩模粗糙更敏感的瞳——预算要联立。</p><h3 id="空白相位粗糙与线边要分桶" tabindex="-1">空白相位粗糙与线边要分桶 <a class="header-anchor" href="#空白相位粗糙与线边要分桶" aria-label="Permalink to &quot;空白相位粗糙与线边要分桶&quot;">​</a></h3><p>多层表面高度的随机相位在亮场像散斑，吸收体 LER 在边沿像位置噪声。修空白用再抛或筛选坯；修线边用写入与干法。混成一个「掩模粗糙 nm」会拧错旋钮。光化显微镜比 DUV SEM 更接近打印，相位项尤其如此。</p>',12)),(e(),i(d,null,{default:E(()=>[h(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ABS%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%E8%BE%B9%E6%B2%BF%20PSD%22%5D%20--%3E%20MEEF%5B%22%E5%85%89%E5%AD%A6%E4%BC%A0%E9%80%92%20%2F%20MEEF%22%5D%0A%20%20ML%5B%22%E5%A4%9A%E5%B1%82%E7%9B%B8%E4%BD%8D%E7%B2%97%E7%B3%99%22%5D%20--%3E%20SPEC%5B%22%E5%AF%B9%E6%AF%94%20%2F%20%E6%95%A3%E6%96%91%E7%B1%BB%E5%99%AA%E5%A3%B0%22%5D%0A%20%20MEEF%20--%3E%20WAFER%5B%22%E7%A1%85%E7%89%87%20LER%20%E5%BA%95%E5%99%AA%22%5D%0A%20%20DOSE%5B%22%E5%8A%A0%E5%89%82%E9%87%8F%22%5D%20--%3E%20PH%5B%22%E5%85%89%E5%AD%90%E9%A1%B9%E4%B8%8B%E9%99%8D%22%5D%0A%20%20PH%20--%3E%20WAFER%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>成像是掩模频谱乘 TCC。边沿位置的随机相位/振幅调制出现在硅片边沿的随机位移。短波长让同样的物理粗糙对应更高的光学频率；部分相干又决定哪些频率进像。相位粗糙相当于随机的弱相位物，贡献类似散斑，在亮场更明显。修复若用沉积补边，可能引入新的局部粗糙峰——下一课的代价。</p><p><span class="marginnote">Naulleau 的公开论述强调：EUV LER 不能单靠胶和剂量解释。掩模贡献要用光化验证，而不是只信 DUV 掩模 SEM。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写电子束或气助修复的工艺窗口，下一课才写 EUV 特有的修复约束。不重写掩模厂 e-beam 写入课。加剂量压胶随机之后，掩模 PSD 会成为 LER 地板，要尽早用光化确认。出处：Naulleau mask roughness；Mack LER；MEEF 通识。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掩模边沿与多层相位粗糙构成不随剂量消失的 LER 底噪。</li><li>高 MEEF 和 EUV 传递把掩模 PSD 放大到硅片。</li><li>下一课：修缺陷时如何避免把粗糙和相位坑修得更糟。</li><li>出处：Naulleau；Mack。</li></ul>',7))])}const S=l(p,[["render",u]]);export{k as __pageData,S as default};
